15	pub(crate) enum Answer {
16	    Props(Props),
17	    /// The component keeps its structural result, for this reason.
18	    Fallback(String),
19	    /// A generic component, whose props are read from an instantiation of it ([`crate::instantiate`]).
20	    Instantiate(Instantiation),
21	}
