24	pub(crate) struct Props {
25	    pub(crate) props: Vec<Arc<SemanticProp>>,
26	    /// See [`caliper_docgen_core::types::semantic::SemanticComponent::composes`].
27	    pub(crate) composes: Option<Vec<String>>,
28	}
