40	/// A module as the checker reads it: its own symbol, whose declaration names its file in the checker's spelling, and
41	/// its exports.
42	pub(crate) struct Module {
43	    pub(crate) symbol: SymbolInfo,
44	    pub(crate) exports: Vec<SymbolInfo>,
45	}
46	
47	impl Module {
48	    /// Whether one of `symbol`'s declarations is in this module's file.
49	    fn declares(&self, symbol: &SymbolInfo) -> bool {
50	        let files: Vec<&str> = self.symbol.declarations.iter().map(|declaration| declared_in(declaration)).collect();
51	        symbol.declarations.iter().any(|declaration| files.contains(&declared_in(declaration)))
52	    }
53	}
54	
55	/// The symbol `export` names in `module`: the export of exactly that name, through an alias to what it aliases, then
56	/// each property an attached sub-component is reached through. `Err` says why there is none, or why it is not the
57	/// component the extractor found: one declared in another file.
58	async fn exported_symbol(
59	    rpc: &Rpc,
60	    module: &Module,
61	    export: &ComponentExport,
62	) -> Result<Result<SymbolInfo, String>, CallError> {
63	    let Some(symbol) = module.exports.iter().find(|symbol| symbol.name == export.name) else {
64	        return Ok(Err(format!("the checker finds no export `{}` in its module", export.name)));
65	    };
66	    let mut symbol = if symbol.flags & flag::SYMBOL_ALIAS != 0 {
67	        rpc.aliased_symbol(&symbol.reference).await?
68	    } else {
69	        symbol.clone()
70	    };
71	    for member in &export.members {
72	        let parent = rpc.type_of_symbol(&symbol.reference).await?;
73	        let Some(property) = rpc.properties(parent.id).await?.into_iter().find(|property| property.name == *member)
74	        else {
75	            return Ok(Err(format!("the checker finds no property `{member}` on the export `{}`", export.name)));
76	        };
77	        symbol = property;
78	    }
79	    if !module.declares(&symbol) {
80	        return Ok(Err(format!("the export `{export}` is declared in another file")));
81	    }
82	    Ok(Ok(symbol))
83	}
84	
85	/// The component's symbol: the first export the extractor recorded for it that the checker finds. Never another
86	/// export, such as the module's `default` when `default` is not one of them.
87	async fn component_symbol(
88	    rpc: &Rpc,
89	    module: &Module,
90	    target: &Target,
91	) -> Result<Result<(SymbolInfo, ComponentExport), String>, CallError> {
92	    let mut reasons = Vec::new();
93	    for export in &target.exports {
94	        match exported_symbol(rpc, module, export).await? {
95	            Ok(symbol) => return Ok(Ok((symbol, export.clone()))),
96	            Err(reason) => reasons.push(reason),
97	        }
98	    }
99	    Ok(Err(if reasons.is_empty() { "not exported by its module".to_string() } else { reasons.join("; ") }))
100	}
101	
102	pub(crate) async fn props_of(
103	    rpc: &Rpc,
104	    converter: &Converter,
105	    interner: &PropInterner,
106	    module: &Module,
107	    target: &Target,
108	) -> Result<Answer, CallError> {
109	    let (symbol, export) = match component_symbol(rpc, module, target).await? {
110	        Ok(found) => found,
111	        Err(reason) => return Ok(Answer::Fallback(reason)),
112	    };
113	
114	    let component = rpc.type_of_symbol(&symbol.reference).await?;
115	    let signatures = rpc.signatures(component.id, SignatureKind::Call).await?;
116	    let [signature] = signatures.as_slice() else {
117	        return fallback(if signatures.is_empty() {
118	            "no call signature (class or non-function component)"
119	        } else {
120	            "overloaded call signatures"
121	        });
122	    };
123	    let parameters = rpc.parameters(signature.id).await?;
124	    let Some(first) = parameters.first() else { return fallback("takes no props parameter") };
125	    if let Some(arguments) = instantiate::default_arguments(rpc, signature).await? {
126	        if !export.members.is_empty() {
127	            return fallback("a generic sub-component reached through its parent's property is not instantiated");
128	        }
129	        return Ok(Answer::Instantiate(Instantiation { export: export.name, arguments }));
130	    }
131	
132	    let props_type = rpc.type_of_symbol(&first.reference).await?;
133	    Ok(props_of_type(rpc, converter, interner, &props_type, target).await?.map_or_else(Answer::Fallback, Answer::Props))
134	}
