136	/// The props a component's props type holds, or why the component keeps its structural result.
137	pub(crate) async fn props_of_type(
138	    rpc: &Rpc,
139	    converter: &Converter,
140	    interner: &PropInterner,
141	    props_type: &TypeInfo,
142	    target: &Target,
143	) -> Result<Result<Props, String>, CallError> {
144	    if props_type.flags & (flag::ANY | flag::UNKNOWN | flag::UNION | flag::TYPE_PARAMETER) != 0 {
145	        return Ok(Err("props type is any, unknown, generic or a union".to_string()));
146	    }
147	
148	    let own: Vec<SymbolInfo> = rpc
149	        .properties(props_type.id)
150	        .await?
151	        .into_iter()
152	        .filter(|property| {
153	            !is_react_declared(property)
154	                || target.react_wanted.as_ref().is_none_or(|wanted| wanted.contains(&property.name))
155	        })
156	        .collect();
157	    let references: Vec<_> = own.iter().map(|property| &property.reference).collect();
158	    let types = if references.is_empty() { Vec::new() } else { converter.types_of_symbols(&references).await? };
159	
160	    // React's own descriptions and tags are the structural pass's to give, and its props are most of a component's.
161	    let asked: Vec<Asked<'_>> = own
162	        .iter()
163	        .map(|property| {
164	            let react_declared = is_react_declared(property);
165	            Asked {
166	                property,
167	                description: !react_declared && !target.described.contains(&property.name),
168	                tags: !react_declared,
169	            }
170	        })
171	        .collect();
172	    let keys: Vec<PropKey> = asked
173	        .iter()
174	        .zip(&types)
175	        .map(|(asked, prop_type)| PropKey::of(asked.property, prop_type, asked.description, asked.tags))
176	        .collect();
177	    let mut props: Vec<Option<Arc<SemanticProp>>> = keys.iter().map(|key| converter.known_prop(key)).collect();
178	    let missing: Vec<usize> = (0..props.len()).filter(|index| props.get(*index).is_some_and(Option::is_none)).collect();
179	    let unknown_types: Vec<TypeInfo> =
180	        missing.iter().filter_map(|index| types.get(*index).map(|info| TypeInfo::clone(info))).collect();
181	    let converted = converter.convert_roots(&unknown_types).await?;
182	    let unknown_asked: Vec<Asked<'_>> = missing
183	        .iter()
184	        .filter_map(|index| asked.get(*index))
185	        .map(|asked| Asked { property: asked.property, description: asked.description, tags: asked.tags })
186	        .collect();
187	    let declared = converter.declared(&unknown_asked).await?;
188	    let mut keys: Vec<Option<PropKey>> = keys.into_iter().map(Some).collect();
189	    for ((index, prop_type), declared) in missing.iter().zip(converted).zip(declared) {
190	        let (Some(property), Some(key)) = (own.get(*index), keys.get_mut(*index).and_then(Option::take)) else {
191	            continue;
192	        };
193	        let required = property.flags & flag::SYMBOL_OPTIONAL == 0;
194	        let prop = interner.share(SemanticProp {
195	            name: property.name.clone(),
196	            prop_type: without_undefined(prop_type, !required),
197	            required,
198	            description: declared.description,
199	            tags: declared.tags,
200	            parent: declared.parent,
201	            declarations: declared.declarations,
202	            react_declared: is_react_declared(property),
203	        });
204	        converter.keep_prop(key, prop.clone());
205	        if let Some(slot) = props.get_mut(*index) {
206	            *slot = Some(prop);
207	        }
208	    }
209	    let props: Vec<Arc<SemanticProp>> = props.into_iter().flatten().collect();
210	    let composes = converter.composes(props_type).await?;
211	    Ok(Ok(Props { props, composes }))
212	}
