350	#[allow(clippy::too_many_arguments)]
351	fn apply_props(
352	    entry: &mut ComponentEntry,
353	    semantic: &SemanticComponent,
354	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
355	    memo: &mut MergeMemo,
356	    syntax: &SourceSyntax,
357	    resolver: ResolverFacts,
358	    cx: CollapseContext,
359	) -> MergedProps {
360	    // The whole-project merge replaces the props and leaves `@types/react`'s to the inheritance layers. A component
361	    // with no layer has nowhere to leave them: a context's `Provider` (`value`, `children`) or a `th`/`td` attribute
362	    // intersection names no element. Its `@types/react` props the structural pass lists stay, as the curated mode
363	    // keeps them (`targets_of` asks the checker for those names only, `key` among them only if the component lists it).
364	    let layered = !entry.inheritance.is_empty();
365	    let own: Vec<&Arc<SemanticProp>> = semantic
366	        .props
367	        .iter()
368	        .filter(|prop| !prop.react_declared || (!layered && entry.props.contains_key(&prop.name)))
369	        .collect();
370	    let (own, notable) = layer_checker_props(entry, own, cx);
371	    let merge = Merge { composes: semantic.composes.as_deref(), unanswered: Unanswered::Drop, syntax, resolver };
372	    let merged = replace_props(entry, own.into_iter(), &merge, shared, memo);
373	    move_notable(entry, &notable);
374	    merged
375	}
