377	/// The checker's `props` for `entry` without those an inherited source collapsed into a layer holds, and the notable
378	/// ones to move to `notableInherited` once merged ([`move_notable`]).
379	///
380	/// The collapse decision has one owner, [`CollapseInheritedProps::collapses`](crate::types::options::CollapseInheritedProps::collapses),
381	/// asked with a source's declared member count. Both lanes supply that count: the structural resolver for the sources
382	/// it reads, which are its layers here; the checker (`sources`) for a source the structural answer did not read (no
383	/// structural prop and no layer has it as its source), decided by `cx` ([`CollapseContext::collapses`]).
384	///
385	/// 1. A prop a collapsed layer names (`InheritedLayer::members`) is left to it, unless the structural answer lists the
386	///    prop itself (the component declares it again).
387	/// 2. A source only the checker read becomes a collapsed layer when the owner collapses it, asked with the members
388	///    that reach the component: the props of the answer whose `parent` is the source, after any `Omit` or `Pick`, each
389	///    name once (the structural resolver counts the same; no declared count is asked of the checker). `members` are those props and `totalProps` their number,
390	///    what the layer holds. Its notable props move to `notableInherited`, as the structural resolver keeps a collapsed
391	///    source's notable members.
392	///
393	/// Applying it again to the entry it changed gives the same props and layers: a layer made here is then a layer of the
394	/// entry, which the first rule follows.
395	pub(crate) fn layer_checker_props<'a>(
396	    entry: &mut ComponentEntry,
397	    props: Vec<&'a Arc<SemanticProp>>,
398	    cx: CollapseContext,
399	) -> (Vec<&'a Arc<SemanticProp>>, Vec<(String, PropParent)>) {
400	    // Each source the answer names (a prop's `parent` is an interface), in the order it first names it, with the
401	    // members of it that reach the component, each once.
402	    let mut sources: Vec<(&'a PropParent, Vec<String>)> = Vec::new();
403	    for prop in props.iter().filter(|prop| !prop.react_declared) {
404	        let Some(parent) = prop.parent.as_ref() else { continue };
405	        match sources.iter_mut().find(|(source, _)| *source == parent) {
406	            Some((_, names)) if !names.contains(&prop.name) => names.push(prop.name.clone()),
407	            Some(_) => {}
408	            None => sources.push((parent, vec![prop.name.clone()])),
409	        }
410	    }
411	    let unread = |source: &PropParent| {
412	        !entry.props.values().any(|prop| prop.parent.as_ref() == Some(source))
413	            && !entry
414	                .inheritance
415	                .iter()
416	                .any(|layer| layer.type_name == source.name && layer.file_name == source.file_name)
417	    };
418	    let notable_names = crate::react_types::notable_html_attrs("");
419	    let mut notable = Vec::new();
420	    let mut layers = Vec::new();
421	    for (source, members) in sources {
422	        if !unread(source) || !cx.collapses(&source.file_name, &source.name, members.len()) {
423	            continue;
424	        }
425	        notable.extend(
426	            members
427	                .iter()
428	                .filter(|name| notable_names.contains(&name.as_str()))
429	                .map(|name| (name.clone(), source.clone())),
430	        );
431	        layers.push(InheritedLayer {
432	            type_name: source.name.clone(),
433	            file_name: source.file_name.clone(),
434	            omitted: Vec::new(),
435	            html_element: None,
436	            total_props: u32::try_from(members.len()).unwrap_or(u32::MAX),
437	            members,
438	        });
439	    }
440	    entry.inheritance.extend(layers);
441	    let layered: rustc_hash::FxHashSet<&str> =
442	        entry.inheritance.iter().flat_map(|layer| layer.members.iter().map(String::as_str)).collect();
443	    if layered.is_empty() {
444	        return (props, notable);
445	    }
446	    let kept = props
447	        .into_iter()
448	        .filter(|prop| {
449	            notable.iter().any(|(name, _)| *name == prop.name)
450	                || entry.props.contains_key(&prop.name)
451	                || !layered.contains(prop.name.as_str())
452	        })
453	        .collect();
454	    (kept, notable)
455	}
