use order::Placed;
use syntax::SourceSyntax;

/// The type of a name the checker could not resolve (an import that does not resolve, a name declared nowhere), which
/// the checker answers with its error type: an `any` that is not a written `any`. It is `opaque` with the reason
/// `unresolvableImport`, so the prop carries `degradedBy`, and `written` is the name as the source writes it, which is
/// also what the reason names (the checker does not say which module specifier was behind it).
pub fn unresolved_type(written: impl Into<String>) -> PropType {
    let written = written.into();
    #[allow(
        clippy::disallowed_methods,
        reason = "the checker's error type is an unresolvable name; the caller reports it"
    )]
    OpaqueDetail::new(written.clone(), OpaqueReason::UnresolvableImport { specifier: written })
}

/// A type the checker holds that PropType has no shape for: a conditional or indexed access type it could not resolve
/// (its parameters are still open), `keyof T`. It is `opaque` with `reason`, so the prop carries `degradedBy`, and
/// `raw` is how the checker prints it.
pub fn degraded_type(raw: impl Into<String>, reason: OpaqueReason) -> PropType {
    #[allow(clippy::disallowed_methods, reason = "the checker names the reason; the caller reports it")]
    OpaqueDetail::new(raw, reason)
}

/// One prop as the checker reports it.
#[derive(Debug, Clone, PartialEq)]
pub struct SemanticProp {
    /// The prop's name as written in the props type.
    pub name: String,
    /// The type the checker computed for it, in the same shape the structural resolver produces.
    pub prop_type: PropType,
    /// Whether the checker found the prop non-optional.
    pub required: bool,
    /// The prop's JSDoc description, empty when it has none; the merge then keeps the structural description.
    pub description: String,
    /// The prop's JSDoc tags (`@deprecated`, `@since`, `@default`), each by name with the text the checker renders, empty
    /// when it has none; the merge then keeps the structural tags, as for `description`. `@types/react`'s props are not
    /// asked for theirs.
    pub tags: BTreeMap<String, String>,
    /// The interface that declares the prop, as react-docgen-typescript states it: the parent of its first declaration
    /// when that is an interface, with the file it is in. `None` for a prop declared in a type literal or with no
    /// declaration. It replaces the structural `parent`, `None` included.
    pub parent: Option<PropParent>,
    /// The interface of each declaration that is in one, in the checker's order: two when an intersection or a merged
    /// interface declares the prop twice.
    pub declarations: Vec<PropParent>,
    /// Declared by `@types/react` (`children`, `aria-*`, handlers, `className`): not the component's own prop.
    pub react_declared: bool,
}

impl SemanticProp {
}

/// Where a prop was declared — enables RDT propFilter compatibility.
/// The canonical RDT pattern: `prop => !prop.parent.fileName.includes('node_modules')`
#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct PropParent {
    /// Name of the interface/type alias that declared this prop
    pub name: String,
    /// Absolute path of the file — matches RDT's `fileName` field
    pub file_name: String,
}

// ─── PropType — The Canonical Semantic Type Representation ────────────────────

/// Semantic type of a prop. Rich enough to produce any output format.
/// Use match exhaustively — no `_` fallthrough in serializers.
#[derive(Debug, Clone, PartialEq)]
pub enum PropType {
    // ── Primitives
    /// `string`.
    String,
    /// `number`.
    Number,
    /// `boolean`; a `true | false` union is collapsed into this.

        assert_eq!(
            line,
            "import type { \"default\" as CaliperComponent3 } from \"/p/src/Poly.tsx\"; export type CaliperProbe3 = \
             Parameters<typeof CaliperComponent3<\"div\">>[0]; export type CaliperSignature3 = typeof \
             CaliperComponent3; export type CaliperArgument3_0 = \"div\";"
        );
    }

    #[test]
    fn a_path_with_quotes_or_backslashes_stays_one_string() {
        let instantiation = Instantiation { export: "Poly".to_string(), arguments: vec!["string".to_string()] };

        let line = probe_line(0, Utf8Path::new("C:\\p\\a\"b.tsx"), &instantiation);

        assert!(line.contains(r#"from "C:\\p\\a\"b.tsx";"#), "{line}");
    }

    /// ADR 0026's S5 gate: `Poly<"div">` has at least 260 props, and `Anchor<"a">`, the same props at another default,
    /// others. An instantiation is always at the defaults, so a second element is a second component.
    #[test]
    #[allow(clippy::unwrap_used, clippy::expect_used, clippy::print_stderr)]
    fn a_polymorphic_component_has_the_props_of_the_element_it_is_instantiated_with() {
        let root = camino::Utf8PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/generic");
        let file = root.join("Poly.tsx");
        let target = |name: &str| Target {
            key: name.to_string(),
            file_path: file.clone(),
            display_name: name.to_string(),
            exports: vec![caliper_docgen_core::types::ComponentExport::named("Poly")],
            described: Default::default(),
            react_wanted: None,
        };
        let at = |export: &str, element: &str| Instantiation {
            export: export.to_string(),
            arguments: vec![format!("\"{element}\"")],
        };
        let timeout = std::time::Duration::from_secs(60);
        let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap();

        let outcome = runtime.block_on(async {
            let checker = crate::checker::Backend::start(&root, 1).unwrap();
            let tsconfig = root.join("tsconfig.json");
            let files = [file.to_string()];
            let rpc = Rpc::open_programs(checker.client(), timeout, Some(tsconfig.as_str()), &files, false, 1)
                .await
                .unwrap()
                .remove(0);
            let pending = vec![(target("Poly<div>"), at("Poly", "div")), (target("Poly<a>"), at("Anchor", "a"))];
            let outcome = answer(&rpc, &files, &root, &PropInterner::default(), false, pending).await.unwrap();
            rpc.release().await;
            checker.shutdown().await;
            outcome
        });

        assert_eq!(outcome.fallbacks, []);
        let names = |display: &str| -> Vec<String> {
            let component = outcome.components.iter().find(|c| c.key == display).expect("answered");
            component.props.iter().map(|prop| prop.name.clone()).collect()
        };
        let (div, a) = (names("Poly<div>"), names("Poly<a>"));
        assert!(div.len() >= 260, "Poly<\"div\"> has {} props", div.len());
        assert_ne!(div, a);
        assert!(a.contains(&"href".to_string()) && !div.contains(&"href".to_string()));
        eprintln!("Poly<\"div\">: {} props, Poly<\"a\">: {} props", div.len(), a.len());
    }
}
