        if let Some(first) = answer.get(0).and_then(|property| property["name"].as_str()) {
            *lists.entry(first.to_string()).or_insert(0) += 1;
        }
    };
    for call in calls {
        match call["method"].as_str() {
            Some("getPropertiesOfType") => count(&call["result"]),
